import fs from 'node:fs';
import path from 'node:path';

const rootDir = process.cwd();
const distDir = path.join(rootDir, 'dist');

// Ensure dist directory exists and is clean
if (fs.existsSync(distDir)) {
  fs.rmSync(distDir, { recursive: true, force: true });
}
fs.mkdirSync(distDir, { recursive: true });

// Copy all files from .output/public to dist if present (JS/CSS chunks, favicon, etc.)
// NOTE: .output/public/index.html (and _shell.html) are generated by TanStack Start
// with a broken "/src/main.tsx" dev reference — we ALWAYS overwrite index.html below.
const outputPublicDir = path.join(rootDir, '.output', 'public');
if (fs.existsSync(outputPublicDir)) {
  fs.cpSync(outputPublicDir, distDir, { recursive: true });
}

// Copy all files from .amplify-hosting/static to dist if present
const amplifyStaticDir = path.join(rootDir, '.amplify-hosting', 'static');
if (fs.existsSync(amplifyStaticDir)) {
  fs.cpSync(amplifyStaticDir, distDir, { recursive: true, force: true });
}

// Copy public/ folder to dist/ (favicon, robots.txt, etc.)
const publicDir = path.join(rootDir, 'public');
if (fs.existsSync(publicDir)) {
  fs.cpSync(publicDir, distDir, { recursive: true, force: true });
}

// Locate the hashed CSS and JS entry files produced by Vite/TanStack Start.
// The filenames contain a content hash so we must discover them dynamically.
const assetsDir = path.join(distDir, 'assets');
let cssAssetTag = '';
let jsAssetTag  = '';

if (fs.existsSync(assetsDir)) {
  const assetFiles = fs.readdirSync(assetsDir);

  // CSS: styles-<hash>.css
  const cssFile = assetFiles.find(f => f.startsWith('styles-') && f.endsWith('.css'));
  if (cssFile) {
    cssAssetTag = `<link rel="stylesheet" href="/assets/${cssFile}" />`;
  }

  // JS entry: index-<hash>.js  (TanStack Start SPA client entry)
  const jsFile = assetFiles.find(f => f.startsWith('index-') && f.endsWith('.js'));
  if (jsFile) {
    jsAssetTag = `<script type="module" src="/assets/${jsFile}"></script>`;
    console.log(`✅ JS entry: /assets/${jsFile}`);
  } else {
    console.error('❌ Could not locate index-*.js in dist/assets — listing files:');
    console.error(assetFiles.join('\n'));
    process.exit(1);
  }
}

// Write the production index.html.
// TanStack Start SPA mode (spa: { enabled: true, prerender: { enabled: false } })
// initialises window.$_TSR client-side inside the JS bundle — no server injection needed.
const indexHtml = `<!doctype html>
<html lang="en">
  <head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <title>Monexa — Personal Financial Intelligence Platform</title>
    <meta name="description" content="Personal Financial Intelligence Platform with AI-powered simulations and deterministic calculations." />
    <link rel="preconnect" href="https://fonts.googleapis.com" />
    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
    <link href="https://fonts.googleapis.com/css2?family=Instrument+Serif:ital@0;1&family=Plus+Jakarta+Sans:wght@400;500;600;700&display=swap" rel="stylesheet" />
    <link rel="icon" href="/favicon.ico" type="image/x-icon" />
    ${cssAssetTag}
  </head>
  <body>
    <div id="root"></div>
    ${jsAssetTag}
  </body>
</html>
`;

fs.writeFileSync(path.join(distDir, 'index.html'), indexHtml);

// Remove .amplify-hosting directory so Amplify only deploys from dist/
const amplifyDir = path.join(rootDir, '.amplify-hosting');
if (fs.existsSync(amplifyDir)) {
  fs.rmSync(amplifyDir, { recursive: true, force: true });
}

const distContents = fs.readdirSync(distDir);
console.log(`✅ dist/ contents: ${distContents.join(', ')}`);
console.log('✅ Generated pure static SPA bundle in dist/ (AWS Amplify S3/CloudFront ready)');
